package org.sleepwell.app;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.Consumer;
/** Explicit-Test-only owner. A cancelled/blocked native close retains the process lease. */
final class SonarRuntime {
 interface Factory {SonarPump.Io open(SonarConfig config,AtomicBoolean cancelled)throws Exception;}
 static final class State {final String phase,message;final SonarFrame frame;final boolean busy,ready;State(String phase,String message,SonarFrame frame,boolean busy,boolean ready){this.phase=phase;this.message=message;this.frame=frame;this.busy=busy;this.ready=ready;}}
 private static final AtomicReference<Object> OWNER=new AtomicReference<>();private final Object token=new Object();private final Factory factory;private final Executor ui;private final Consumer<State> listener;private final SonarPump.Clock clock;private final AtomicBoolean cancelled=new AtomicBoolean();private final CountDownLatch ended=new CountDownLatch(1);private volatile State state=new State("IDLE","Test the current phone placement.",null,false,false);private Thread worker;private final java.util.ArrayDeque<SonarFrame> frames=new java.util.ArrayDeque<>();
 synchronized java.util.List<SonarFrame> snapshot(){return java.util.List.copyOf(frames);}
 private synchronized void retain(SonarFrame frame){frames.addLast(frame);while(frames.size()>375)frames.removeFirst();}
 SonarRuntime(Factory factory,Executor ui,Consumer<State> listener,SonarPump.Clock clock){this.factory=factory;this.ui=ui;this.listener=listener;this.clock=clock;}
 State state(){return state;}
 boolean ready(){return state.ready&&!cancelled.get();}
 synchronized boolean start(SonarConfig config){if(worker!=null||!OWNER.compareAndSet(null,token))return false;publish(new State("TESTING","Preparing speaker and microphone…",null,true,false));worker=new Thread(()->{try{SonarFrame[] latest={null};long[] published={Long.MIN_VALUE};State terminal;boolean[] released={true};boolean uncertain=false;try{if(cancelled.get())throw new InterruptedException();SonarPump.Io nativeIo=factory.open(config,cancelled);released[0]=false;SonarPump.Io io=new AcknowledgedIo(nativeIo,released);SonarFrame last=SonarPump.run(io,config,cancelled,clock,frame->{latest[0]=frame;retain(frame);long at=clock.millis();if(published[0]==Long.MIN_VALUE||at-published[0]>=200){published[0]=at;publish(new State("TESTING",copy(frame),frame,true,false));}});boolean ready=!cancelled.get()&&last!=null&&last.quality==SonarFrame.Quality.VALID;terminal=new State(cancelled.get()?"CANCELLED":"DONE",cancelled.get()?"Test cancelled. Tap Test signal to begin again.":ready?"Echo movement detected. Hardware accuracy is unverified.":"No verified moving echo. Reposition the phone and test again.",last,false,ready);}catch(Exception|LinkageError failure){uncertain=!released[0]||uncertain(failure);terminal=uncertain?new State("BLOCKED","Audio cleanup could not be confirmed. Restart SleepWell before another test.",latest[0],false,false):new State(cancelled.get()?"CANCELLED":"ERROR",cancelled.get()?"Test cancelled. Tap Test signal to begin again.":failure.getMessage()==null?"Contactless sensing is unavailable.":failure.getMessage(),latest[0],false,false);}finally{if(released[0]&&!uncertain)OWNER.compareAndSet(token,null);}publish(terminal);}finally{ended.countDown();}},"SleepWell-sonar");worker.start();return true;}
 private static boolean uncertain(Throwable error){if(error instanceof SonarPump.CleanupFailure)return true;for(Throwable child:error.getSuppressed())if(uncertain(child))return true;return error.getCause()!=null&&error.getCause()!=error&&uncertain(error.getCause());}
 private static final class AcknowledgedIo implements SonarPump.Io {final SonarPump.Io io;final boolean[] released;AcknowledgedIo(SonarPump.Io io,boolean[] released){this.io=io;this.released=released;}public void startMuted()throws Exception{io.startMuted();}public void check()throws Exception{io.check();}public boolean routed(){return io.routed();}public void confirmRoutes()throws Exception{io.confirmRoutes();}public SonarPump.Timing timing()throws Exception{return io.timing();}public int write(short[] p,int a,int n)throws Exception{return io.write(p,a,n);}public int read(short[] p,int a,int n)throws Exception{return io.read(p,a,n);}public void gain(float g)throws Exception{io.gain(g);}public void close(){io.close();released[0]=true;}}
 void cancel(){cancelled.set(true);if(!state.busy&&state.ready)publish(new State("CANCELLED","Test cancelled. Test again before saving.",state.frame,false,false));if(state.busy)publish(new State("CLOSING","Stopping speaker and microphone…",state.frame,true,false));Thread current=worker;if(current!=null)current.interrupt();}
 boolean awaitClosed(long millis)throws InterruptedException{return ended.await(millis,TimeUnit.MILLISECONDS);}
 private State current(State next){return next.ready&&cancelled.get()?new State("CANCELLED","Test cancelled. Test again before saving.",next.frame,false,false):next;}
 private void publish(State next){state=current(next);ui.execute(()->listener.accept(current(next)));}
 static String copy(SonarFrame f){return switch(f.quality){case VALID->"Echo movement detected";case CALIBRATING->"Measuring stationary reflections…";case NEEDS_MOVEMENT->"Move gently in front of the phone to check reflections.";case NO_ECHO->"No usable reflection. Face the speaker toward your body.";case CLIPPED->"Microphone signal clipped. Reduce gain or increase distance.";case TIMING_LOST->"Audio timing changed. Test again.";default->"Signal unavailable: "+f.quality.name().toLowerCase(java.util.Locale.ROOT);};}
}
